DROP VIEW "public"."catalogued_books";--> statement-breakpoint
DROP VIEW "public"."queued_books";--> statement-breakpoint
DROP VIEW "public"."shelved_books";--> statement-breakpoint
ALTER TABLE "books" ADD COLUMN "title_search_json" text DEFAULT '' NOT NULL;--> statement-breakpoint
CREATE VIEW "public"."catalogued_books" AS (select "books"."id", "books"."isbn13", "books"."isbn10", "books"."title", "books"."subtitle", "books"."authors", "books"."publisher", "books"."published", "books"."pages", "books"."notes", "books"."shelf_range", "books"."classification_source", "books"."classification_confidence", "books"."series_name", "books"."series_index", "books"."title_filing", "books"."sort_key", "books"."lookup_source", "books"."cover_checked_at", "books"."isbn_source", "books"."ocr_text", "books"."scanned_at", "books"."state", "books"."title_guess", "books"."cover_text", "books"."analysed", "books"."draft_json", "books"."edit_json", "books"."edited_by", "books"."edited_at", "books"."scan_note", "books"."claimed_by", "books"."claimed_at", "books"."processed_at", "books"."read_attempts", "books"."title_search_json", "books"."current_area_id", coalesce("author_alias"."filing_name", '') as "author_filing" from "books" left join "book_author" on ("book_author"."book_id" = "books"."id" and "book_author"."position" = 1) left join "author_alias" on "author_alias"."id" = "book_author"."author_alias_id" where "books"."state" in ('shelved', 'checked_out', 'withdrawn'));--> statement-breakpoint
CREATE VIEW "public"."queued_books" AS (select "books"."id", "books"."isbn13", "books"."isbn10", "books"."title", "books"."subtitle", "books"."authors", "books"."publisher", "books"."published", "books"."pages", "books"."notes", "books"."shelf_range", "books"."classification_source", "books"."classification_confidence", "books"."series_name", "books"."series_index", "books"."title_filing", "books"."sort_key", "books"."lookup_source", "books"."cover_checked_at", "books"."isbn_source", "books"."ocr_text", "books"."scanned_at", "books"."state", "books"."title_guess", "books"."cover_text", "books"."analysed", "books"."draft_json", "books"."edit_json", "books"."edited_by", "books"."edited_at", "books"."scan_note", "books"."claimed_by", "books"."claimed_at", "books"."processed_at", "books"."read_attempts", "books"."title_search_json", "books"."current_area_id", coalesce("author_alias"."filing_name", '') as "author_filing" from "books" left join "book_author" on ("book_author"."book_id" = "books"."id" and "book_author"."position" = 1) left join "author_alias" on "author_alias"."id" = "book_author"."author_alias_id" where "books"."state" in ('scanned', 'unidentified', 'identified'));--> statement-breakpoint
CREATE VIEW "public"."shelved_books" AS (select "books"."id", "books"."isbn13", "books"."isbn10", "books"."title", "books"."subtitle", "books"."authors", "books"."publisher", "books"."published", "books"."pages", "books"."notes", "books"."shelf_range", "books"."classification_source", "books"."classification_confidence", "books"."series_name", "books"."series_index", "books"."title_filing", "books"."sort_key", "books"."lookup_source", "books"."cover_checked_at", "books"."isbn_source", "books"."ocr_text", "books"."scanned_at", "books"."state", "books"."title_guess", "books"."cover_text", "books"."analysed", "books"."draft_json", "books"."edit_json", "books"."edited_by", "books"."edited_at", "books"."scan_note", "books"."claimed_by", "books"."claimed_at", "books"."processed_at", "books"."read_attempts", "books"."title_search_json", "books"."current_area_id", coalesce("author_alias"."filing_name", '') as "author_filing" from "books" left join "book_author" on ("book_author"."book_id" = "books"."id" and "book_author"."position" = 1) left join "author_alias" on "author_alias"."id" = "book_author"."author_alias_id" where "books"."state" = 'shelved');